import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Triplet Margin Loss
triplet_margin_loss_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void triplet_margin_loss_kernel(const float* anchor, const float* positive, const float* negative, float* out, float margin, int batch_size, int feature_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size) {
        float dist_pos = 0.0f;
        float dist_neg = 0.0f;
        for (int i = 0; i < feature_size; ++i) {
            float diff_pos = anchor[idx * feature_size + i] - positive[idx * feature_size + i];
            float diff_neg = anchor[idx * feature_size + i] - negative[idx * feature_size + i];
            dist_pos += diff_pos * diff_pos;
            dist_neg += diff_neg * diff_neg;
        }
        dist_pos = sqrtf(dist_pos);
        dist_neg = sqrtf(dist_neg);
        out[idx] = fmaxf(0.0f, dist_pos - dist_neg + margin);
    }
}

torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, float margin) {
    auto batch_size = anchor.size(0);
    auto feature_size = anchor.size(1);
    auto out = torch::zeros({batch_size}, anchor.options());

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    triplet_margin_loss_kernel<<<num_blocks, block_size>>>(anchor.data_ptr<float>(), positive.data_ptr<float>(), negative.data_ptr<float>(), out.data_ptr<float>(), margin, batch_size, feature_size);

    return out.mean();
}
"""

triplet_margin_loss_cpp_source = (
    "torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, float margin);"
)

# Compile the inline CUDA code for Triplet Margin Loss
triplet_margin_loss = load_inline(
    name="triplet_margin_loss",
    cpp_sources=triplet_margin_loss_cpp_source,
    cuda_sources=triplet_margin_loss_source,
    functions=["triplet_margin_loss_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    """
    A model that computes Triplet Margin Loss for metric learning tasks using custom CUDA kernels.

    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = margin
        self.triplet_margin_loss = triplet_margin_loss

    def forward(self, anchor, positive, negative):
        return self.triplet_margin_loss.triplet_margin_loss_cuda(anchor, positive, negative, self.margin)
